#!/usr/bin/env python3
"""Magnitude sweep analysis: norm sensitivity curve for perdof vs obs_only on spatial benchmark."""

import json
import os
import re
import sys

import yaml
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import numpy as np

# ── paths ──────────────────────────────────────────────────────────────
REGISTRY = os.path.join(os.path.dirname(__file__), "..", "registry.yaml")
OUT_DIR = os.path.join(os.path.dirname(__file__), "figures")
os.makedirs(OUT_DIR, exist_ok=True)

# ── experiment ID patterns ─────────────────────────────────────────────
# Magnitude sweep experiments follow: eval-mag-{method}-norm{nnn}
MAG_PERDOF_PREFIX = "eval-mag-perdof-norm"
MAG_OBSONLY_PREFIX = "eval-mag-obsonly-norm"

# Also include norm=0.1 baseline runs (original spatial evals)
PERDOF_NORM01 = "eval-acr-spatial-v4-small"      # perdof, norm=0.1 (7/10 partial)
PERDOF_NORM01_R2 = "eval-acr-spatial-v4-small-r2" # restart tasks 8-10
OBSONLY_NORM01 = "eval-acr-spatial-v4-obs-only-r2" # obs_only, norm=0.1
OBSONLY_NORM01_R3 = "eval-acr-spatial-v4-obs-only-r3" # restart

# Baselines
RECONVLA_ARGMIN = "eval-reconvla-spatial-v3"  # 34%
VLA_ONLY = "eval-spatial-v7-full"              # 30%
VLA_MEAN = "eval-vla-mean-spatial"             # 32%


def load_registry():
    with open(REGISTRY) as f:
        return yaml.safe_load(f)


def normalize_sr(val):
    """Normalize success rate to 0-1 scale, handling mixed registry formats."""
    if isinstance(val, str):
        val = float(val.strip("%")) / 100 if "%" in val else float(val)
    val = float(val)
    if val > 1:
        val = val / 100
    return val


def extract_overall_sr(exp):
    """Extract overall success rate from experiment metrics, handling inconsistent field names."""
    m = exp.get("metrics", {})
    if not m:
        return None

    for key in ("overall_success_rate", "overall_sr", "overall_success_rate_10tasks",
                "overall_SR", "avg_SR_10task", "overall_sr_10task"):
        if key in m:
            return normalize_sr(m[key])

    # Try computing from per_task
    per_task = m.get("per_task", {})
    if per_task and len(per_task) == 10:
        return sum(normalize_sr(v) for v in per_task.values()) / len(per_task)

    return None


def extract_partial_sr(exp):
    """Extract SR from partial results (in-progress experiments)."""
    m = exp.get("metrics", {})
    if not m:
        return None, 0

    partial = m.get("partial_results", {})
    if partial:
        successes = 0
        trials = 0
        for v in partial.values():
            match = re.search(r"\((\d+)/(\d+)\)", str(v))
            if match:
                successes += int(match.group(1))
                trials += int(match.group(2))
        if trials > 0:
            return successes / trials, len(partial)
        return None, 0

    per_task_partial = m.get("per_task_partial", {})
    if per_task_partial:
        normalized = [normalize_sr(v) for v in per_task_partial.values()]
        return sum(normalized) / len(normalized), len(per_task_partial)

    # Try running_avg fields
    for key, val in m.items():
        if key.startswith("running_avg"):
            match = re.search(r"([\d.]+)%", str(val))
            if match:
                return float(match.group(1)) / 100.0, int(re.search(r"(\d+)tasks?", key).group(1)) if re.search(r"(\d+)tasks?", key) else 0
    return None, 0


NORM_LOOKUP = {
    "003": 0.03, "005": 0.05, "01": 0.1, "02": 0.2, "03": 0.3,
    "0p03": 0.03, "0p05": 0.05, "0p1": 0.1, "0p2": 0.2, "0p3": 0.3,
}


def parse_norm_from_id(exp_id, prefix):
    """Parse norm value from experiment ID like eval-mag-perdof-norm003 -> 0.03."""
    suffix = exp_id[len(prefix):]
    norm_part = suffix.split("-")[0]

    if not norm_part:
        return None

    if norm_part in NORM_LOOKUP:
        return NORM_LOOKUP[norm_part]

    if "p" in norm_part:
        try:
            return float(norm_part.replace("p", "."))
        except ValueError:
            return None

    if norm_part.startswith("0") and len(norm_part) >= 2 and norm_part.isdigit():
        return float("0." + norm_part.lstrip("0"))

    try:
        return float("0." + norm_part)
    except ValueError:
        return None


def merge_partial_results(exps, base_id, restart_ids):
    """Merge base + restart partial results into combined SR."""
    all_results = {}

    for eid in [base_id] + restart_ids:
        if eid not in exps:
            continue
        m = exps[eid].get("metrics", {})

        # From per_task (completed)
        for k, v in m.get("per_task", {}).items():
            short = k.replace("pick_up_black_bowl_", "")
            all_results[short] = normalize_sr(v)

        # From partial_results
        for k, v in m.get("partial_results", {}).items():
            short = k.replace("pick_up_black_bowl_", "")
            match = re.search(r"([\d.]+)%", str(v))
            if match:
                all_results[short] = float(match.group(1)) / 100.0

        # From per_task_partial
        for k, v in m.get("per_task_partial", {}).items():
            short = k.replace("pick_up_black_bowl_", "")
            all_results[short] = normalize_sr(v)

    if all_results:
        return sum(all_results.values()) / len(all_results), len(all_results), all_results
    return None, 0, {}


def _is_benchmark(exp_id, exp, benchmark):
    """Check if experiment belongs to the given benchmark (spatial/object)."""
    if benchmark == "object":
        return "object" in exp_id.lower()
    # spatial: no "object" in ID
    return "object" not in exp_id.lower()


def collect_sweep_data(exps, benchmark="spatial"):
    """Collect norm -> SR data for perdof and obs_only methods, filtered by benchmark."""
    perdof_data = {}
    obsonly_data = {}

    for eid, exp in exps.items():
        if exp.get("status") not in ("RUNNING", "DONE"):
            continue
        if exp.get("conclusion") in ("killed", "failed"):
            continue

        if eid.startswith(MAG_PERDOF_PREFIX):
            if not _is_benchmark(eid, exp, benchmark):
                continue
            norm = parse_norm_from_id(eid, MAG_PERDOF_PREFIX)
            if norm is None:
                continue
            sr = extract_overall_sr(exp)
            if sr is None:
                sr, n = extract_partial_sr(exp)
            if sr is not None:
                existing = perdof_data.get(norm)
                if existing is None or exp.get("status") == "DONE":
                    perdof_data[norm] = {"sr": sr, "exp_id": eid, "status": exp.get("status")}

        elif eid.startswith(MAG_OBSONLY_PREFIX):
            if not _is_benchmark(eid, exp, benchmark):
                continue
            norm = parse_norm_from_id(eid, MAG_OBSONLY_PREFIX)
            if norm is None:
                continue
            sr = extract_overall_sr(exp)
            if sr is None:
                sr, n = extract_partial_sr(exp)
            if sr is not None:
                existing = obsonly_data.get(norm)
                if existing is None or exp.get("status") == "DONE":
                    obsonly_data[norm] = {"sr": sr, "exp_id": eid, "status": exp.get("status")}

    # Add norm=0.1 from original spatial evals
    sr_perdof_01, n, _ = merge_partial_results(exps, PERDOF_NORM01, [PERDOF_NORM01_R2])
    if sr_perdof_01 is not None:
        perdof_data[0.1] = {"sr": sr_perdof_01, "exp_id": f"{PERDOF_NORM01}+restart", "status": "MERGED", "n_tasks": n}

    sr_obsonly_01, n, _ = merge_partial_results(exps, OBSONLY_NORM01, [OBSONLY_NORM01_R3])
    if sr_obsonly_01 is not None:
        obsonly_data[0.1] = {"sr": sr_obsonly_01, "exp_id": f"{OBSONLY_NORM01}+restart", "status": "MERGED", "n_tasks": n}

    return perdof_data, obsonly_data


def plot_sensitivity_curve(perdof_data, obsonly_data, baselines):
    """Generate norm sensitivity curve plot."""
    # ── style ──────────────────────────────────────────────────────────
    plt.rcParams.update({
        "font.family": "serif",
        "font.serif": ["Times New Roman", "DejaVu Serif"],
        "font.size": 11,
        "axes.labelsize": 13,
        "axes.titlesize": 14,
        "legend.fontsize": 10,
        "xtick.labelsize": 11,
        "ytick.labelsize": 11,
        "axes.linewidth": 0.8,
        "lines.linewidth": 2.0,
        "lines.markersize": 8,
        "figure.dpi": 150,
    })

    colors = {
        "perdof": "#2E86AB",      # steel blue
        "obs_only": "#A23B72",    # raspberry
        "argmin": "#555555",      # dark gray
        "vla_only": "#999999",    # light gray
        "vla_mean": "#BBBBBB",    # lighter gray
    }

    fig, ax = plt.subplots(figsize=(6.5, 4.5))

    # Plot perdof
    if perdof_data:
        norms = sorted(perdof_data.keys())
        srs = [perdof_data[n]["sr"] * 100 for n in norms]
        markers = ["o" if perdof_data[n].get("status") == "DONE" or perdof_data[n].get("n_tasks", 10) == 10
                   else "^" for n in norms]
        ax.plot(norms, srs, "-o", color=colors["perdof"], label="ACR per-DOF", zorder=5)
        # Mark partial results with open markers
        for i, n in enumerate(norms):
            status = perdof_data[n].get("status")
            n_tasks = perdof_data[n].get("n_tasks", 10)
            if status == "RUNNING" or (n_tasks is not None and n_tasks < 10):
                ax.plot(n, srs[i], "^", color=colors["perdof"], markerfacecolor="white",
                       markeredgewidth=2, markersize=9, zorder=6)

    # Plot obs_only
    if obsonly_data:
        norms = sorted(obsonly_data.keys())
        srs = [obsonly_data[n]["sr"] * 100 for n in norms]
        ax.plot(norms, srs, "-s", color=colors["obs_only"], label="ACR obs-only", zorder=5)
        for i, n in enumerate(norms):
            status = obsonly_data[n].get("status")
            n_tasks = obsonly_data[n].get("n_tasks", 10)
            if status == "RUNNING" or (n_tasks is not None and n_tasks < 10):
                ax.plot(n, srs[i], "D", color=colors["obs_only"], markerfacecolor="white",
                       markeredgewidth=2, markersize=9, zorder=6)

    # Baseline horizontal lines
    xmin, xmax = 0.02, 0.35
    if baselines.get("argmin") is not None:
        ax.axhline(baselines["argmin"] * 100, color=colors["argmin"], ls="--", lw=1.5,
                   label=f"ReconVLA argmin ({baselines['argmin']*100:.0f}%)", zorder=3)
    if baselines.get("vla_mean") is not None:
        ax.axhline(baselines["vla_mean"] * 100, color=colors["vla_mean"], ls=":", lw=1.5,
                   label=f"VLA mean ({baselines['vla_mean']*100:.0f}%)", zorder=2)
    if baselines.get("vla_only") is not None:
        ax.axhline(baselines["vla_only"] * 100, color=colors["vla_only"], ls="-.", lw=1.0,
                   label=f"VLA-only ({baselines['vla_only']*100:.0f}%)", zorder=1)

    ax.set_xlabel("Correction Magnitude (max norm)")
    ax.set_ylabel("Success Rate (%)")
    ax.set_title("Norm Sensitivity: Spatial Benchmark")
    ax.set_xscale("log")
    ax.xaxis.set_major_formatter(mticker.ScalarFormatter())
    ax.xaxis.set_minor_formatter(mticker.NullFormatter())
    ax.set_xticks([0.03, 0.05, 0.1, 0.2, 0.3])
    ax.get_xaxis().set_major_formatter(mticker.FormatStrFormatter("%.2f"))
    ax.set_xlim(xmin, xmax)
    ax.set_ylim(0, 65)
    ax.grid(True, alpha=0.3, ls="-", lw=0.5)
    ax.legend(loc="best", framealpha=0.9, edgecolor="gray")

    # Annotation for open markers
    ax.annotate("Open markers = partial (< 10 tasks)", xy=(0.98, 0.02),
                xycoords="axes fraction", ha="right", va="bottom",
                fontsize=8, color="gray", style="italic")

    fig.tight_layout()
    out_path = os.path.join(OUT_DIR, "magnitude_sweep_spatial.pdf")
    fig.savefig(out_path, bbox_inches="tight", dpi=300)
    print(f"Saved: {out_path}")

    # Also save PNG for quick preview
    png_path = out_path.replace(".pdf", ".png")
    fig.savefig(png_path, bbox_inches="tight", dpi=200)
    print(f"Saved: {png_path}")
    plt.close(fig)


def generate_summary_json(perdof_data, obsonly_data, baselines):
    """Generate JSON summary table."""
    summary = {
        "baselines": {k: v for k, v in baselines.items() if v is not None},
        "perdof": {},
        "obs_only": {},
    }

    argmin_sr = baselines.get("argmin", 0.34)

    for norm in sorted(set(list(perdof_data.keys()) + list(obsonly_data.keys()))):
        norm_str = f"{norm:.2f}"
        if norm in perdof_data:
            sr = perdof_data[norm]["sr"]
            summary["perdof"][norm_str] = {
                "sr": round(sr, 4),
                "sr_pct": f"{sr*100:.1f}%",
                "delta_vs_argmin": f"{(sr - argmin_sr)*100:+.1f}pp",
                "exp_id": perdof_data[norm]["exp_id"],
                "status": perdof_data[norm].get("status", "UNKNOWN"),
            }
        if norm in obsonly_data:
            sr = obsonly_data[norm]["sr"]
            summary["obs_only"][norm_str] = {
                "sr": round(sr, 4),
                "sr_pct": f"{sr*100:.1f}%",
                "delta_vs_argmin": f"{(sr - argmin_sr)*100:+.1f}pp",
                "exp_id": obsonly_data[norm]["exp_id"],
                "status": obsonly_data[norm].get("status", "UNKNOWN"),
            }

    out_path = os.path.join(OUT_DIR, "magnitude_sweep_summary.json")
    with open(out_path, "w") as f:
        json.dump(summary, f, indent=2)
    print(f"Saved: {out_path}")
    return summary


def main():
    benchmark = sys.argv[1] if len(sys.argv) > 1 else "spatial"
    data = load_registry()
    exps = data.get("experiments", {})

    # Collect baseline SRs
    baselines = {}
    for bid, bname in [(RECONVLA_ARGMIN, "argmin"), (VLA_ONLY, "vla_only"), (VLA_MEAN, "vla_mean")]:
        if bid in exps:
            baselines[bname] = extract_overall_sr(exps[bid])

    perdof_data, obsonly_data = collect_sweep_data(exps, benchmark=benchmark)

    # Print status
    print("=" * 60)
    print("MAGNITUDE SWEEP ANALYSIS")
    print("=" * 60)
    print(f"\nBaselines: {', '.join(f'{k}={v*100:.0f}%' for k, v in baselines.items() if v)}")
    print(f"\nPer-DOF data points: {len(perdof_data)}")
    for n in sorted(perdof_data.keys()):
        d = perdof_data[n]
        print(f"  norm={n:.2f}: SR={d['sr']*100:.1f}%  [{d.get('status', '?')}]  ({d['exp_id']})")
    print(f"\nObs-only data points: {len(obsonly_data)}")
    for n in sorted(obsonly_data.keys()):
        d = obsonly_data[n]
        print(f"  norm={n:.2f}: SR={d['sr']*100:.1f}%  [{d.get('status', '?')}]  ({d['exp_id']})")

    if not perdof_data and not obsonly_data:
        print("\n⚠ No magnitude sweep results available yet. Experiments are still RUNNING.")
        print("Re-run this script once experiments have metrics.")
        # Still generate empty JSON
        generate_summary_json(perdof_data, obsonly_data, baselines)
        return

    plot_sensitivity_curve(perdof_data, obsonly_data, baselines)
    summary = generate_summary_json(perdof_data, obsonly_data, baselines)

    print("\n── Summary ──")
    for method in ["perdof", "obs_only"]:
        if summary[method]:
            best_norm = min(summary[method], key=lambda n: -summary[method][n]["sr"])
            print(f"  Best {method}: norm={best_norm}, SR={summary[method][best_norm]['sr_pct']}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Spatial benchmark final analysis: merge partial + restart results, generate comparison table."""

import json
import os
import re
import sys

import yaml
import matplotlib
matplotlib.use("Agg")

# ── paths ──────────────────────────────────────────────────────────────
REGISTRY = os.path.join(os.path.dirname(__file__), "..", "registry.yaml")
OUT_DIR = os.path.join(os.path.dirname(__file__), "figures")
os.makedirs(OUT_DIR, exist_ok=True)

# ── canonical spatial tasks (order from eval-spatial-v7-full) ──────────
SPATIAL_TASKS = [
    "between_plate_and_ramekin",
    "next_to_ramekin",
    "from_table_center",
    "on_cookie_box",
    "in_top_drawer",
    "on_ramekin",
    "next_to_cookie_box",
    "on_stove",
    "next_to_plate",
    "on_wooden_cabinet",
]

TASK_SHORT_TO_FULL = {t: f"pick_up_black_bowl_{t}" for t in SPATIAL_TASKS}

TASK_DISPLAY = {
    "between_plate_and_ramekin": "Betw. Plate\n& Ramekin",
    "next_to_ramekin": "Next to\nRamekin",
    "from_table_center": "Table\nCenter",
    "on_cookie_box": "On Cookie\nBox",
    "in_top_drawer": "In Top\nDrawer",
    "on_ramekin": "On\nRamekin",
    "next_to_cookie_box": "Next to\nCookie Box",
    "on_stove": "On\nStove",
    "next_to_plate": "Next to\nPlate",
    "on_wooden_cabinet": "On Wooden\nCabinet",
}

# ── experiments to merge per method ────────────────────────────────────
# Each method maps to a list of experiment IDs to merge (base + restarts).
# Later experiments overwrite earlier ones for the same task.
SPATIAL_METHODS = {
    "VLA-only (K=1)": {
        "exp_ids": ["eval-spatial-v7-full"],
        "color": "#AAAAAA",
    },
    "VLA-mean (K=10)": {
        "exp_ids": ["eval-vla-mean-spatial", "eval-vla-mean-spatial-t10"],
        "color": "#888888",
    },
    "ReconVLA argmin (K=10)": {
        "exp_ids": ["eval-reconvla-spatial-v3"],
        "color": "#555555",
    },
    "Argmin-only (K=10)": {
        "exp_ids": ["eval-argmin-only-spatial", "eval-argmin-only-spatial-r2"],
        "color": "#777777",
    },
    "ACR per-DOF": {
        "exp_ids": ["eval-acr-spatial-v4-small", "eval-acr-spatial-v4-small-r2"],
        "color": "#2E86AB",
    },
    "ACR obs-only": {
        "exp_ids": ["eval-acr-spatial-v4-obs-only-r2", "eval-acr-spatial-v4-obs-only-r3"],
        "color": "#A23B72",
    },
    "ACR scalar": {
        "exp_ids": ["eval-acr-spatial-v4-scalar", "eval-acr-spatial-v4-scalar-r2"],
        "color": "#E8A838",
    },
    "ACR tiny (norm=0.05)": {
        "exp_ids": ["eval-tiny-correction-spatial"],
        "color": "#6B4C9A",
    },
}

# T-index to task mapping (used by some experiments that report T1-T10)
T_INDEX_MAP = {f"T{i+1}": SPATIAL_TASKS[i] for i in range(10)}
# Also map "on_wooden_shelf" -> "on_wooden_cabinet" (known alias)
TASK_ALIASES = {
    "on_wooden_shelf": "on_wooden_cabinet",
    "between_plate_ramekin": "between_plate_and_ramekin",
}


def load_registry():
    with open(REGISTRY) as f:
        return yaml.safe_load(f)


def normalize_task_name(name):
    """Normalize task name to canonical short form."""
    # Strip full prefix
    name = name.replace("pick_up_black_bowl_", "")
    # Strip T{n}_ prefix (e.g. "T1_between_plate_ramekin" -> "between_plate_ramekin")
    name = re.sub(r"^T\d+_", "", name)
    # T-index mapping (bare "T1", "T2", ...)
    if name in T_INDEX_MAP:
        return T_INDEX_MAP[name]
    # Aliases
    name = TASK_ALIASES.get(name, name)
    # Fuzzy alias match
    for alias, canonical in TASK_ALIASES.items():
        if alias in name:
            return canonical
    return name


def extract_task_results(exp):
    """Extract per-task results from experiment, returning {task_short: sr}."""
    m = exp.get("metrics", {})
    if not m:
        return {}

    results = {}

    # per_task dict (completed experiments)
    for key, val in m.get("per_task", {}).items():
        task = normalize_task_name(key)
        if task in SPATIAL_TASKS:
            results[task] = float(val)

    # partial_results (in-progress, format: "60.0% (6/10)")
    for key, val in m.get("partial_results", {}).items():
        task = normalize_task_name(key)
        if task in SPATIAL_TASKS:
            match = re.search(r"([\d.]+)%", str(val))
            if match:
                results[task] = float(match.group(1)) / 100.0

    # per_task_partial
    for key, val in m.get("per_task_partial", {}).items():
        task = normalize_task_name(key)
        if task in SPATIAL_TASKS:
            results[task] = float(val)

    # Handle T1-T10 at metrics top level (e.g. eval-vla-mean-spatial)
    for key, val in m.items():
        if re.match(r"^T\d+$", key) and key in T_INDEX_MAP:
            task = T_INDEX_MAP[key]
            results[task] = float(val)
        elif re.match(r"^T\d+_", key):
            task = normalize_task_name(key)
            if task in SPATIAL_TASKS:
                if isinstance(val, (int, float)):
                    results[task] = float(val)
                else:
                    match = re.search(r"(\d+)%", str(val))
                    if match:
                        results[task] = float(match.group(1)) / 100.0

    return results


def merge_method_results(exps, exp_ids):
    """Merge results from multiple experiments (base + restarts). Later overwrite earlier."""
    merged = {}
    sources = {}

    for eid in exp_ids:
        if eid not in exps:
            continue
        task_results = extract_task_results(exps[eid])
        for task, sr in task_results.items():
            merged[task] = sr
            sources[task] = eid

    return merged, sources


def collect_all_methods(exps):
    """Collect per-task results for all methods."""
    all_methods = {}

    for method_name, cfg in SPATIAL_METHODS.items():
        merged, sources = merge_method_results(exps, cfg["exp_ids"])
        n_tasks = len(merged)
        overall = sum(merged.values()) / n_tasks if n_tasks > 0 else None

        all_methods[method_name] = {
            "per_task": merged,
            "sources": sources,
            "n_tasks": n_tasks,
            "overall_sr": overall,
            "complete": n_tasks == 10,
            "color": cfg["color"],
        }

    return all_methods


def generate_latex_table(all_methods):
    """Generate LaTeX table: methods × spatial tasks."""
    n_tasks = len(SPATIAL_TASKS)
    col_spec = "l" + "c" * n_tasks + "c"

    lines = []
    lines.append(r"\begin{table*}[t]")
    lines.append(r"\centering")
    lines.append(r"\caption{Spatial Benchmark: Per-Task Success Rate (\%). Best per-task in \textbf{bold}.}")
    lines.append(r"\label{tab:spatial-final}")
    lines.append(r"\resizebox{\textwidth}{!}{%")
    lines.append(r"\begin{tabular}{" + col_spec + "}")
    lines.append(r"\toprule")

    # Header
    header = "Method"
    for t in SPATIAL_TASKS:
        short = t.replace("_", " ").title()
        # Abbreviate long names
        abbrev_map = {
            "Between Plate And Ramekin": "Btw P\\&R",
            "Next To Ramekin": "Nxt Ram",
            "From Table Center": "Tbl Ctr",
            "On Cookie Box": "On CkBx",
            "In Top Drawer": "Top Drw",
            "On Ramekin": "On Ram",
            "Next To Cookie Box": "Nxt CkBx",
            "On Stove": "On Stv",
            "Next To Plate": "Nxt Plt",
            "On Wooden Cabinet": "On WdCb",
        }
        short = abbrev_map.get(short, short[:8])
        header += f" & \\rotatebox{{60}}{{{short}}}"
    header += r" & \textbf{Avg.} \\"
    lines.append(header)
    lines.append(r"\midrule")

    # Find best per task (for bolding)
    best_per_task = {}
    for t in SPATIAL_TASKS:
        best_sr = -1
        for m, mdata in all_methods.items():
            sr = mdata["per_task"].get(t)
            if sr is not None and sr > best_sr:
                best_sr = sr
        if best_sr >= 0:
            best_per_task[t] = best_sr

    # Method rows — baselines first, then ACR variants
    method_order = [
        "VLA-only (K=1)", "VLA-mean (K=10)", "ReconVLA argmin (K=10)", "Argmin-only (K=10)",
        "ACR per-DOF", "ACR obs-only", "ACR scalar", "ACR tiny (norm=0.05)",
    ]
    active_methods = [m for m in method_order if m in all_methods]

    for i, method in enumerate(active_methods):
        if i == 4 and any(m.startswith("ACR") for m in active_methods[i:]):
            lines.append(r"\midrule")

        mdata = all_methods[method]
        row = method.replace("_", r"\_").replace("&", r"\&")
        if not mdata["complete"]:
            row += f"$^{{{mdata['n_tasks']}}}$"

        task_srs = []
        for t in SPATIAL_TASKS:
            sr = mdata["per_task"].get(t)
            if sr is not None:
                val = sr * 100
                task_srs.append(val)
                cell = f"{val:.0f}"
                if t in best_per_task and abs(sr - best_per_task[t]) < 1e-6:
                    cell = f"\\textbf{{{cell}}}"
                row += f" & {cell}"
            else:
                row += " & --"

        # Overall
        if mdata["overall_sr"] is not None:
            avg = mdata["overall_sr"] * 100
            avg_str = f"{avg:.1f}"
            if mdata["complete"]:
                row += f" & \\textbf{{{avg_str}}}"
            else:
                row += f" & {avg_str}$^*$"
        else:
            row += " & --"

        row += r" \\"
        lines.append(row)

    lines.append(r"\bottomrule")
    lines.append(r"\multicolumn{" + str(n_tasks + 2) + r"}{l}{\footnotesize $^n$ = only $n$/10 tasks completed. $^*$ = partial average.} \\")
    lines.append(r"\end{tabular}}")
    lines.append(r"\end{table*}")

    latex = "\n".join(lines)

    out_path = os.path.join(OUT_DIR, "spatial_final_table.tex")
    with open(out_path, "w") as f:
        f.write(latex)
    print(f"Saved: {out_path}")

    return latex


def generate_json_summary(all_methods):
    """Generate JSON summary of all spatial results."""
    summary = {}

    for method, mdata in all_methods.items():
        summary[method] = {
            "per_task": {t: mdata["per_task"].get(t) for t in SPATIAL_TASKS},
            "overall_sr": mdata["overall_sr"],
            "n_tasks": mdata["n_tasks"],
            "complete": mdata["complete"],
            "sources": mdata["sources"],
        }

    out_path = os.path.join(OUT_DIR, "spatial_final_data.json")
    with open(out_path, "w") as f:
        json.dump(summary, f, indent=2)
    print(f"Saved: {out_path}")

    return summary


def main():
    data = load_registry()
    exps = data.get("experiments", {})
    all_methods = collect_all_methods(exps)

    print("=" * 60)
    print("SPATIAL BENCHMARK - FINAL COMPARISON")
    print("=" * 60)

    # Summary table
    header = f"{'Method':<28} {'Tasks':>5} {'Overall':>8}  Status"
    print(f"\n{header}")
    print("-" * len(header))

    for method, mdata in all_methods.items():
        sr_str = f"{mdata['overall_sr']*100:.1f}%" if mdata['overall_sr'] else "N/A"
        status = "COMPLETE" if mdata['complete'] else f"PARTIAL ({mdata['n_tasks']}/10)"
        print(f"{method:<28} {mdata['n_tasks']:>5} {sr_str:>8}  {status}")

    # Per-task detail
    print(f"\n{'Task':<30}", end="")
    method_names = list(all_methods.keys())
    for m in method_names:
        print(f" {m[:12]:>12}", end="")
    print()
    print("-" * (30 + 13 * len(method_names)))

    for t in SPATIAL_TASKS:
        print(f"{t:<30}", end="")
        for m in method_names:
            sr = all_methods[m]["per_task"].get(t)
            if sr is not None:
                print(f" {sr*100:>11.0f}%", end="")
            else:
                print(f" {'--':>12}", end="")
        print()

    # Improvement analysis
    print("\n── ACR vs Baselines ──")
    baselines = {
        "VLA-only (K=1)": all_methods.get("VLA-only (K=1)", {}).get("overall_sr"),
        "ReconVLA argmin (K=10)": all_methods.get("ReconVLA argmin (K=10)", {}).get("overall_sr"),
    }

    for method in all_methods:
        if not method.startswith("ACR"):
            continue
        mdata = all_methods[method]
        if mdata["overall_sr"] is None:
            continue

        sr = mdata["overall_sr"]
        for bname, bsr in baselines.items():
            if bsr is not None:
                delta = (sr - bsr) * 100
                rel = (sr - bsr) / bsr * 100 if bsr > 0 else float("inf")
                suffix = f"({'PARTIAL' if not mdata['complete'] else 'FULL'})"
                print(f"  {method} vs {bname}: {delta:+.1f}pp ({rel:+.1f}% relative) {suffix}")

    # Generate outputs
    latex = generate_latex_table(all_methods)
    summary = generate_json_summary(all_methods)

    print("\n── LaTeX Table ──")
    print(latex)


if __name__ == "__main__":
    main()

